// P4a acceptance tests: the S1 sign-off list made permanent. Every ACCEPTED
// semantic from docs/v2-s1-metadata-findings.md §4 is asserted against the
// S1 corpus (generated by testdata/gen_corpus.py, ground truth in
// testdata/manifest.json, v1 reference values in testdata/gold_v1.json from
// music-metadata@11.14.0).

package audio

import (
	"math"
	"path/filepath"
	"testing"
)

// corpusFile is one row of the parity table: the full v1-equivalent schema
// for one corpus file. Zero/nil means "absent" (v1 `?? undefined`).
type corpusFile struct {
	name string

	title        string
	artist       string
	artists      []string
	album        string
	albumArtist  string
	albumArtists []string
	trackNo      int
	trackTotal   int
	discNo       int
	discTotal    int
	year         int
	date         string
	genres       []string
	composers    []string
	producers    []string
	labels       []string
	releaseType  string
	comment      string
	bpm          int

	mbidRecording    string
	mbidRelease      string
	mbidReleaseGroup string
	mbidAlbumArtist  string
	mbidArtistIDs    []string

	barcode string
	asin    string
	isrcs   []string

	replayGainTrack float64
	replayGainAlbum float64

	explicit    *bool
	compilation *bool

	lyrics       string
	syncedLyrics []SyncedLyricLine

	hasCoverArt bool
	pictureMime string
	pictureSize int

	duration      float64 // gold_v1.json format.duration
	bitrate       int     // gold format.bitrate (m4a: see tolerance note)
	sampleRate    int
	channels      int
	bitsPerSample int
}

