func boolPtr(b bool) *bool { return &b }

func TestReadMetadataParity(t *testing.T) {
	for _, tc := range spikeFiles {
		t.Run(tc.name, func(t *testing.T) {
			md, err := ReadMetadata(filepath.Join("testdata", "corpus", tc.name))
			if err != nil {
				t.Fatalf("ReadMetadata: %v", err)
			}

			eqStr := func(field, got, want string) {
				t.Helper()
				if got != want {
					t.Errorf("%s = %q, want %q", field, got, want)
				}
			}
			eqInt := func(field string, got, want int) {
				t.Helper()
				if got != want {
					t.Errorf("%s = %d, want %d", field, got, want)
				}
			}
			eqSlice := func(field string, got, want []string) {
				t.Helper()
				if len(got) == 0 && len(want) == 0 {
					return
				}
				if len(got) != len(want) {
					t.Errorf("%s = %v, want %v", field, got, want)
					return
				}
				for i := range got {
					if got[i] != want[i] {
						t.Errorf("%s = %v, want %v", field, got, want)
						return
					}
				}
			}

			eqStr("Title", md.Title, tc.title)
			eqStr("Artist", md.Artist, tc.artist)
			eqSlice("Artists", md.Artists, tc.artists)
			eqStr("Album", md.Album, tc.album)
			eqStr("AlbumArtist", md.AlbumArtist, tc.albumArtist)
			eqSlice("AlbumArtists", md.AlbumArtists, tc.albumArtists)
			eqInt("TrackNo", md.TrackNo, tc.trackNo)
			eqInt("TrackTotal", md.TrackTotal, tc.trackTotal)
			eqInt("DiscNo", md.DiscNo, tc.discNo)
			eqInt("DiscTotal", md.DiscTotal, tc.discTotal)
			eqInt("Year", md.Year, tc.year)
			eqStr("Date", md.Date, tc.date)
			eqSlice("Genres", md.Genres, tc.genres)
			eqSlice("Composers", md.Composers, tc.composers)
			eqSlice("Producers", md.Producers, tc.producers)
			eqSlice("Labels", md.Labels, tc.labels)
			eqStr("ReleaseType", md.ReleaseType, tc.releaseType)
			eqStr("Comment", md.Comment, tc.comment)
			eqInt("BPM", md.BPM, tc.bpm)
			eqStr("MBIDRecording", md.MBIDRecording, tc.mbidRecording)
			eqStr("MBIDRelease", md.MBIDRelease, tc.mbidRelease)
			eqStr("MBIDReleaseGroup", md.MBIDReleaseGroup, tc.mbidReleaseGroup)
			eqStr("MBIDAlbumArtist", md.MBIDAlbumArtist, tc.mbidAlbumArtist)
			eqSlice("MBIDArtistIDs", md.MBIDArtistIDs, tc.mbidArtistIDs)
			eqStr("Barcode", md.Barcode, tc.barcode)
			eqStr("ASIN", md.ASIN, tc.asin)
			eqSlice("ISRCs", md.ISRCs, tc.isrcs)
			if math.Abs(md.ReplayGainTrack-tc.replayGainTrack) > 1e-9 {
				t.Errorf("ReplayGainTrack = %v, want %v", md.ReplayGainTrack, tc.replayGainTrack)
			}
			if math.Abs(md.ReplayGainAlbum-tc.replayGainAlbum) > 1e-9 {
				t.Errorf("ReplayGainAlbum = %v, want %v", md.ReplayGainAlbum, tc.replayGainAlbum)
			}
			if (md.Explicit == nil) != (tc.explicit == nil) || (md.Explicit != nil && *md.Explicit != *tc.explicit) {
				t.Errorf("Explicit = %v, want %v", md.Explicit, tc.explicit)
			}
			if (md.Compilation == nil) != (tc.compilation == nil) || (md.Compilation != nil && *md.Compilation != *tc.compilation) {
				t.Errorf("Compilation = %v, want %v", md.Compilation, tc.compilation)
			}
			eqStr("Lyrics", md.Lyrics, tc.lyrics)

			if len(md.SyncedLyrics) != len(tc.syncedLyrics) {
				t.Errorf("SyncedLyrics = %v, want %v", md.SyncedLyrics, tc.syncedLyrics)
			} else {
				for i := range md.SyncedLyrics {
					if md.SyncedLyrics[i] != tc.syncedLyrics[i] {
						t.Errorf("SyncedLyrics[%d] = %+v, want %+v", i, md.SyncedLyrics[i], tc.syncedLyrics[i])
					}
				}
			}

			if md.HasCoverArt != tc.hasCoverArt {
				t.Errorf("HasCoverArt = %v, want %v", md.HasCoverArt, tc.hasCoverArt)
			}
			if tc.hasCoverArt {
				if md.Picture == nil {
					t.Fatal("Picture is nil, want cover art")
				}
				eqStr("Picture.MIMEType", md.Picture.MIMEType, tc.pictureMime)
				eqInt("len(Picture.Data)", len(md.Picture.Data), tc.pictureSize)
			} else if md.Picture != nil {
				t.Errorf("Picture = %+v, want nil", md.Picture)
			}
		})
	}
}

// TestPathologicalID3v1Latin1 pins the W4 shim against the exact gold_v1.json
// strings (which carry the U+0086 control byte from the source Latin-1).
func TestPathologicalID3v1Latin1(t *testing.T) {
	md, err := ReadMetadata(filepath.Join("testdata", "corpus", "pathological-id3v1.mp3"))
	if err != nil {
		t.Fatalf("ReadMetadata: %v", err)
	}
	wantTitle := "Café naïve"
	wantArtist := "Björk \u0086 stray ÿ" // gold: "Björk \x86 stray ÿ"
	if md.Title != wantTitle {
		t.Errorf("Title = %q, want %q", md.Title, wantTitle)
	}
	if md.Artist != wantArtist {
		t.Errorf("Artist = %q, want %q", md.Artist, wantArtist)
	}
	if len(md.Artists) != 1 || md.Artists[0] != wantArtist {
		t.Errorf("Artists = %q, want [%q]", md.Artists, wantArtist)
	}
	if md.Album != "Séance" {
		t.Errorf("Album = %q, want %q", md.Album, "Séance")
	}
	if md.Comment != "Comment with é accent" {
		t.Errorf("Comment = %q, want %q", md.Comment, "Comment with é accent")
	}
}

// TestUnitDecodeID3v1Latin1 unit-tests the 5-line shim directly.
func TestUnitDecodeID3v1Latin1(t *testing.T) {
	cases := []struct {
		in, want string
	}{
		{"Caf\xe9 na\xefve", "Café naïve"},
		{"Bj\xf6rk \x86 stray \xff", "Björk \u0086 stray ÿ"},
		{"already utf-8 é", "already utf-8 é"}, // valid UTF-8 passes through
		{"plain ASCII", "plain ASCII"},
	}
	for _, c := range cases {
		if got := decodeID3v1Latin1(c.in); got != c.want {
			t.Errorf("decodeID3v1Latin1(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestParseLrc(t *testing.T) {
	got := parseLrc("[00:00.00]Synced line one\n[00:01.50]Synced line two\n")
	want := spikeSynced
	if len(got) != len(want) {
		t.Fatalf("parseLrc = %v, want %v", got, want)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("parseLrc[%d] = %+v, want %+v", i, got[i], want[i])
		}
	}
}
